if(act==='choices'){dialog('Выборы персонажа',`<div class="stack">${select('style','Боевой стиль',opt('','Нет',c.choices.fightingStyle)+['defense','archery','dueling','great-weapon-fighting','protection','two-weapon-fighting'].map(x=>opt(x,x,c.choices.fightingStyle)).join(''))}${c.classes.map(x=>select('sub-'+x.id,C.name('classes',x.id)+' · подкласс',opt('','Не выбран',x.subclass)+(C.get('classes',x.id)?.subclasses||[]).map(s=>opt(s.index,s.name,x.subclass)).join(''))).join('')}<label>Особенности на выбор (id через запятую)<textarea name="features">${esc(c.featureChoices.join(', '))}</textarea></label></div><details><summary>Доступные записи особенностей</summary><div class="prose">${C.list('features').filter(x=>c.classes.some(cl=>cl.id===x.class?.index&&cl.level>=x.level)).map(x=>esc(x.index)+' — '+esc(x.name)).join('\n')}</div></details><p class="notice">Требования к выбору и взаимоисключения проверяются по тексту SRD. Defense, Archery, Dueling и Two-Weapon Fighting включены в формулы; GWF и Protection требуют решения игрока.</p>`,async f=>{await mutate(c=>{c.choices.fightingStyle=f.get('style');for(const x of c.classes)x.subclass=f.get('sub-'+x.id);c.featureChoices=f.get('features').split(',').map(x=>x.trim()).filter(Boolean);A.log(c,'Выборы и подклассы изменены')})},'Сохранить');return}
