if(act==='custom-resource'){dialog('Собственный ресурс',`<div class="form-grid">${input('name','Название','','text','required')}${input('max','Максимум',1,'number','min="1" max="10000"')}${select('recharge','Восстановление',['short','long','dawn','manual','custom'].map(x=>opt(x,recharge(x),'long')).join(''))}${input('condition','Свое условие восстановления','')}</div><p class="notice">Ресурсы со своим условием восстанавливаются явной коррекцией в форме ниже.</p><div class="form-section"><h3>Коррекция существующих ресурсов: осталось</h3><div class="form-grid">${R.resources(c).map(r=>input('res-'+r.id,r.name,r.max-r.used,'number',`min="0" max="${r.max}"`)).join('')}</div>${check('onlyEdit','Только скорректировать существующие (название любое)')}</div>`,async f=>{await mutate(c=>{for(const r of R.resources(c))c.resourceUsed[r.id]=r.max-num(f,'res-'+r.id);if(!yes(f,'onlyEdit'))c.customResources.push({id:'custom-'+Ch.uid(),name:f.get('name'),max:num(f,'max'),recharge:f.get('recharge'),condition:f.get('condition')});A.log(c,'Ресурсы изменены')})},'Сохранить');return}if(act==='time'){dialog('Игровое время',`<p class="notice">Сейчас: ${gameTime(c)}. Таймеры эффектов меняются только при продвижении игрового времени, а не по часам устройства.</p><div class="form-grid form-section">${input('amount','Сколько времени прошло',1,'number','min="0" max="8760"')}${select('unit','Единица',opt('60','Минуты','60')+opt('3600','Часы','60')+opt('6','Раунды','60'))}</div>`,async f=>{await mutate(c=>A.time(c,num(f,'amount')*num(f,'unit')),'Время обновлено')},'Продвинуть');return}if(act==='delete'){dialog('Удалить '+c.name+'?',`<p>Персонаж будет удалён из списка. Удаление можно отменить кнопкой ↶. Для отдельной копии сначала экспортируйте JSON.</p>`,async()=>{await S.change(s=>{s.characters=s.characters.filter(x=>x.id!==c.id);s.active=s.characters[0]?.id||null});page='characters'},'Удалить');return}
